// Minimal inline SVG icon set (stroke-based, inherits currentColor).
// A few icons are supplied as filled artwork on their own canvas instead of
// 24x24 stroke line-art. ICON_META lets those opt out of the stroke defaults
// without touching every other icon.
const ICON_META = {
  settings: { viewBox: "0 0 48 48", fill: "currentColor", stroke: "none" },
};

export function Icon({ name, size = 18, ...rest }) {
  const paths = ICONS[name] || ICONS.dot;
  const meta = ICON_META[name];
  return (
    <svg
      width={size}
      height={size}
      viewBox={meta?.viewBox ?? "0 0 24 24"}
      fill={meta?.fill ?? "none"}
      stroke={meta?.stroke ?? "currentColor"}
      strokeWidth="1.9"
      strokeLinecap="round"
      strokeLinejoin="round"
      {...rest}
    >
      {paths}
    </svg>
  );
}

